import {STORAGE_KEY,uid,loadState,addEvent,startIncident,endIncident,startTrip,finishTrip,advanceTime,validPhone,validateContact,validatePins,remaining,clock} from './model.js';
import {icon} from './icons.js';
import {createRealUI} from './real-ui.js';
let mode='demo';try{if(localStorage.getItem('alerta-rd-mode')==='real')mode='real';}catch{}
const realUI=createRealUI({onChange:()=>{if(mode==='real')render();},onDemo:()=>setMode('demo'),notify:(...args)=>toast(...args)});
function setMode(next){if(next==='demo'&&realUI.hasActive()){toast('Hay un SOS real pendiente. Cancélalo en SOS o espera su resultado antes de cambiar de modo.',true);return;}if(state.incident&&next==='real'){toast('Termina o cancela el SOS de demostración antes de cambiar de modo.');return;}mode=next;try{localStorage.setItem('alerta-rd-mode',mode);}catch{}render();if(mode==='real')realUI.init();}
document.addEventListener('click',e=>{const b=e.target.closest('[data-mode]');if(b)setMode(b.dataset.mode);});
let browserStorage; try { browserStorage=window.localStorage; } catch {}
const loaded=loadState(browserStorage); let state=loaded.state;
const app=document.querySelector('#app'),dialog=document.querySelector('#modal'),toastEl=document.querySelector('#toast');
const pageIds=['sos','drive','help','route','more','history','contacts','security','profile'];
let page=pageIds.includes(location.hash.slice(1))?location.hash.slice(1):'sos';
let physicalOpen=false;
let modal=null,securityTab='pins',driveEditing=false,profileEditing=false,recording=false,practice=false,patternDraft=[],practiceInput=[],patternMessage='',geo={status:'idle'},networkConsent=false,toastTimer,returnFocus;
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const date=at=>new Intl.DateTimeFormat('es-DO',{day:'2-digit',month:'short',year:'numeric'}).format(at);
const time=at=>new Intl.DateTimeFormat('es-DO',{hour:'2-digit',minute:'2-digit'}).format(at);
const initials=name=>name.trim().split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase();
const badge=(label,tone='muted')=>`<span class="badge ${tone}">${label}</span>`;
const button=(label,action,cls='secondary',extra='')=>`<button type="button" class="btn ${cls}" data-action="${action}" ${extra.replace(/type="button"/g,'')}>${label}</button>`;
const heading=(over,title,description,actions='')=>`<header class="page-heading"><div><p class="eyebrow">${over}</p><h1>${title}</h1><p class="subtitle">${description}</p></div>${actions}</header>`;
const note=(text,tone='')=>`<div class="notice ${tone}">${icon('info')}<p>${text}</p></div>`;
const empty=(ic,title,description,action='')=>`<div class="empty"><span class="empty-icon">${icon(ic)}</span><h3>${title}</h3><p>${description}</p>${action}</div>`;
function persist(){try{browserStorage.setItem(STORAGE_KEY,JSON.stringify(state));}catch{toast('No se pudo guardar en este navegador. Los cambios se conservarán solo durante esta sesión.',true);}}
function toast(message,error=false){clearTimeout(toastTimer);toastEl.textContent=message;toastEl.className=`toast visible ${error?'error':''}`;toastTimer=setTimeout(()=>toastEl.classList.remove('visible'),5500);}
function navigate(next){if(page!==next)location.hash=next;else render();}
window.addEventListener('hashchange',()=>{page=pageIds.includes(location.hash.slice(1))?location.hash.slice(1):'sos';profileEditing=false;render();window.scrollTo({top:0});document.querySelector('h1')?.focus({preventScroll:true});});
const navItems=[['sos','shield','SOS'],['drive','car','Drive'],['help','users','Ayuda'],['route','route','Ruta'],['more','menu','Más']];
function activePage(){return ['history','contacts','security','profile'].includes(page)?'more':page;}
function navButtons(cls){return navItems.map(([id,ic,label])=>`<button class="${cls} ${activePage()===id?'active':''}" data-page="${id}" ${activePage()===id?'aria-current="page"':''}>${icon(ic)}<span>${label}</span>${id==='drive'&&state.drive.active?'<span class="nav-dot" aria-label="Drive activo"></span>':''}</button>`).join('');}
function render(){
 const views={sos:renderSOS,drive:renderDrive,help:renderHelp,route:renderRoute,more:renderMore,history:renderHistory,contacts:renderContacts,security:renderSecurity,profile:renderProfile};
 app.innerHTML=`<aside class="sidebar"><a class="brand" href="#sos"><span class="brand-mark">${icon('shield')}</span><span>ALERTA <b>RD</b><small>CONTIGO, SIEMPRE</small></span></a><div class="nav-label">TU ESPACIO DE SEGURIDAD</div><nav aria-label="Navegación principal">${navButtons('side-link')}</nav><div class="side-divider"></div><div class="nav-label">PERSONAL</div><nav aria-label="Configuración personal">${[['history','history','Central / Historial'],['contacts','users','Contactos'],['security','lock','Seguridad'],['profile','user','Perfil']].map(([id,ic,label])=>`<button class="side-link small ${page===id?'active':''}" data-page="${id}">${icon(ic)}<span>${label}</span></button>`).join('')}</nav><div class="sidebar-bottom"><div class="local-note">${icon('lock')}<div><strong>Tu espacio, tus datos</strong><small>${mode==='demo'?'Guardados en este navegador':'Cuenta privada en Supabase'}</small></div></div><button class="profile-mini" data-page="profile"><span class="avatar">${mode==='real'?'TÚ':state.profile.name?esc(initials(state.profile.name)):'TÚ'}</span><span><strong>${mode==='real'?esc(realUI.accountName()):esc(state.profile.name||'Tu perfil')}</strong><small>${state.profile.name?'Ver información personal':'Completa tu información'}</small></span>${icon('chevron')}</button></div></aside><div class="workspace"><header class="topbar"><a class="mobile-brand" href="#sos">${icon('shield')}<strong>ALERTA <b>RD</b></strong></a><div class="breadcrumb">Mi espacio <span>/</span> ${({sos:'Centro de seguridad',drive:'Alerta RD Drive',help:'Red de Ayuda',route:'En Camino',more:'Más opciones',history:'Central / Historial',contacts:'Contactos',security:'Seguridad',profile:'Perfil'})[page]}</div><div class="top-actions">${mode==='demo'?badge('<span class="demo-dot"></span> DEMOSTRACIÓN','demo'):badge('CUENTA · SOS REAL','red')}<button class="icon-button" data-page="history" aria-label="Abrir historial">${icon('history')}</button></div></header>${mode==='demo'?`<div class="demo-strip">${icon('info')}<span>Estás en una demo. <strong>Las simulaciones no envían alertas reales.</strong></span><button data-action="about" aria-label="Información de la demostración">${icon('chevron')}</button></div>`:`<div class="demo-strip real-strip">${icon('shield')}<span>Espacio de cuenta. <strong>El SOS puede enviar mensajes reales cuando esté habilitado.</strong></span></div>`}<div class="mode-switch" role="group" aria-label="Modo de la aplicación"><span>ELIGE TU EXPERIENCIA</span><button data-mode="demo" aria-pressed="${mode==='demo'}">Demostración</button><button data-mode="real" aria-pressed="${mode==='real'}">Cuenta / SOS real</button></div><main id="main" tabindex="-1">${mode==='real'?realUI.view(page):views[page]()}</main><footer class="desktop-footer"><span>ALERTA RD <span class="footer-dot">·</span> Tecnología al servicio de tu tranquilidad</span><span>${mode==='demo'?'Demostración local':'Cuenta conectada'} <span class="footer-dot">·</span> v2.0</span></footer></div><nav class="bottom-nav" aria-label="Navegación inferior">${navButtons('bottom-link')}</nav>`;
 document.querySelector('h1')?.setAttribute('tabindex','-1');updateTimers();
}
function renderSOS(){return `${heading('CENTRO DE SEGURIDAD','Tu tranquilidad empieza aquí.','Todo lo que necesitas, a un toque de distancia.',badge('Espacio de práctica','green'))}<div class="sos-layout"><section class="card sos-card"><div class="card-top"><span class="section-label">ASISTENCIA INMEDIATA</span>${badge('MODO DEMO','red')}</div><div class="sos-orbit"><div class="orbit-mark m1"></div><div class="orbit-mark m2"></div><button class="sos-button" data-action="sos" aria-label="Iniciar SOS de demostración"><span>SOS</span><small>PULSA PARA SIMULAR</small></button></div><h2>Estamos contigo.</h2><p class="sos-description">Inicia una prueba de emergencia.<br>Tendrás 10 segundos para cancelarla.</p><div class="quick-actions"><button data-action="location"><span>${icon('pin')}</span>Mi ubicación</button><button data-action="call"><span>${icon('phone')}</span>Llamar</button><button data-action="assistance"><span>${icon('shield')}</span>Asistencia</button></div><div class="sos-card-footer">${icon('lock')} Entorno seguro de demostración. Sin alertas externas.</div></section><div class="sos-right"><section class="card drive-preview"><div class="card-top"><span class="icon-tile blue">${icon('car')}</span>${badge(state.drive.active?'ACTIVO · DEMO':'EN TUS TRAYECTOS',state.drive.active?'green':'muted')}</div><h2>Muévete con tranquilidad.</h2><p>Alerta RD Drive te acompaña en el camino. Explora cómo funciona la detección simulada de impactos.</p><button class="text-link" data-page="drive">${state.drive.active?'Ver protección demo':'Configurar Drive'} ${icon('arrow')}</button><div class="mini-wave" aria-hidden="true">${[12,19,12,28,17,38,64,31,16,30,17,25,15,12,30,48,76,43,22,34,18,12,22,13,18,35,16,12].map(h=>`<i style="height:${h}%"></i>`).join('')}</div></section><section class="card circle-card"><div class="card-top"><h3>Tu círculo de confianza</h3>${icon('users')}</div><p>Ten a mano a quienes más importan.</p>${state.contacts.length?`<div class="contact-preview">${state.contacts.slice(0,3).map(c=>`<span class="avatar" title="${esc(c.name)}">${esc(initials(c.name))}</span>`).join('')}<span>${state.contacts.length} contacto${state.contacts.length===1?'':'s'} guardado${state.contacts.length===1?'':'s'}</span></div>`:`<div class="contact-placeholder"><span class="dashed-avatar">${icon('plus')}</span><span>Aún no tienes contactos</span></div>`}<button class="text-link" data-page="contacts">${state.contacts.length?'Gestionar contactos':'Agregar mi primer contacto'} ${icon('chevron')}</button></section><button class="simulation-card" data-action="accident"><span class="icon-tile amber">${icon('activity')}</span><span><strong>Simular accidente</strong><small>Explora el protocolo paso a paso · Demo</small></span>${icon('chevron')}</button></div></div><section class="card physical-card"><button class="disclosure" data-action="physical" aria-expanded="${Boolean(physicalOpen)}"><span class="icon-tile">${icon('volume')}</span><span><strong>SOS físico</strong><small>Practica un patrón de botones dentro de la web</small></span>${badge('SIMULACIÓN')} ${icon('down',physicalOpen?'rotated':'')}</button>${physicalOpen?renderPhysical():''}</section><div class="recent-heading"><h3>Actividad reciente</h3><button class="text-link" data-page="history">Ver historial ${icon('chevron')}</button></div>${state.history.length?`<div class="card">${eventRow(state.history[0])}</div>`:`<div class="recent-empty">${icon('history')} Tus pruebas aparecerán aquí. Empieza cuando quieras.</div>`}`;}
function renderPhysical(){return `<div class="physical-content">${note('Los botones de esta página representan teclas de volumen. No se detectan teclas físicas ni se solicitan permisos de accesibilidad.')}<label class="field-label">Patrón guardado</label><div class="pattern">${state.pattern.map(x=>`<kbd>${x}</kbd>`).join('')}</div><div class="button-row">${button('Grabar nuevo patrón','record-pattern')}${button(practice?'Finalizar práctica':'Probar patrón','practice-pattern',practice?'primary':'secondary')}</div>${recording||practice?`<div class="practice-box"><strong>${recording?'Graba entre 3 y 6 pulsaciones':'Repite el patrón guardado'}</strong><div class="button-row">${button('VOL +','pattern-plus')}${button('VOL −','pattern-minus')}</div><p class="pattern-live" aria-live="polite">${(recording?patternDraft:practiceInput).join(' → ')||'Esperando pulsaciones…'}</p>${recording?button('Guardar patrón','save-pattern','primary',patternDraft.length<3?'disabled':''):''}${button('Reiniciar pulsaciones','reset-pattern','ghost')}</div>`:''}<p class="success-text" role="status">${esc(patternMessage)}</p></div>`;}
function renderDrive(){const d=state.drive;return `${heading('SEGURIDAD EN MOVIMIENTO','Alerta RD Drive','Tu próximo trayecto, con un plan de seguridad.')} ${d.active&&!driveEditing?`<div class="two-columns"><section class="card active-drive"><span class="large-icon green">${icon('car')}</span>${badge('SIMULACIÓN','green')}<h2>Protección activa</h2><p>Modo demostración · página abierta</p><div class="monitor"><div class="card-top"><h3>Monitor adaptativo</h3><span class="pulse-dot"></span></div><div class="signal-line" aria-hidden="true">${icon('activity')}</div><dl class="facts"><div><dt>Estado</dt><dd>En espera de una prueba</dd></div><div><dt>Transporte</dt><dd>${esc(d.transport)}</dd></div><div><dt>Detección</dt><dd>Simulada, sin sensores</dd></div></dl></div>${button(`${icon('activity')} Simular impacto (demo)`,'drive-impact','primary full')}</section><section class="card"><p class="eyebrow">A TU MEDIDA</p><h2>Preferencias guardadas</h2><dl class="facts"><div><dt>Transporte habitual</dt><dd>${esc(d.transport)}</dd></div><div><dt>Dispositivo en</dt><dd>${esc(d.placement)}</dd></div><div><dt>Cuenta regresiva</dt><dd>${d.seconds} segundos</dd></div><div><dt>Consentimiento</dt><dd class="green-text">Aceptado</dd></div></dl>${note('Esta demo no detecta accidentes reales. No realiza monitoreo con la pantalla cerrada y no comparte tu ubicación.')}<div class="stack">${button('Reconfigurar','drive-config')}${button('Desactivar Drive','drive-off','danger-outline')}</div></section></div>`:`<form id="drive-form" class="two-columns"><section class="card"><span class="icon-tile red">${icon('shield')}</span><h2>Antes de empezar</h2><p>Conoce los límites de esta experiencia.</p><div class="feature-list">${feature('activity','Detección de demostración','Tú inicias el impacto simulado. Esta versión no lee sensores ni detecta accidentes.')}${feature('pin','Ubicación bajo tu control','Solo se solicita al usar «Mi ubicación». No se transmite durante las pruebas.')}${feature('clock','Tiempo para responder','Elige cuánto tiempo tendrás para cancelar la cuenta regresiva.')}</div><label class="checkbox-line"><input name="consent" type="checkbox" ${d.consent?'checked':''} required><span>Entiendo los límites y acepto activar esta demostración.</span></label></section><section class="card"><h2>Personaliza tu experiencia</h2><fieldset><legend>Transporte habitual</legend><div class="option-grid">${['Automóvil','Motocicleta'].map(x=>`<label class="option"><input type="radio" name="transport" value="${x}" ${d.transport===x?'checked':''} required>${icon('car')}<span>${x}</span></label>`).join('')}</div></fieldset><fieldset><legend>Ubicación del dispositivo</legend><div class="placement-grid">${['Bolsillo','Mochila','Soporte','Cartera'].map(x=>`<label class="option"><input type="radio" name="placement" value="${x}" ${d.placement===x?'checked':''} required><span>${x}</span></label>`).join('')}</div></fieldset><label class="range-label" for="seconds">Cuenta regresiva <output id="seconds-output">${d.seconds} segundos</output></label><input type="range" name="seconds" id="seconds" min="5" max="60" step="5" value="${d.seconds}"><div class="range-hints"><span>5 segundos</span><span>60 segundos</span></div><p class="form-hint">Acepta el consentimiento y elige ambas preferencias para continuar.</p><p class="form-error" role="alert"></p><button id="drive-submit" class="btn primary full" type="submit" ${d.consent&&d.transport&&d.placement?'':'disabled'}>${driveEditing?'Guardar y continuar':'Activar Alerta RD Drive'}</button>${driveEditing?button('Cancelar cambios','drive-config-cancel','ghost full'):''}</section></form>`}`;}
function feature(ic,title,text){return `<div class="feature">${icon(ic)}<div><h3>${title}</h3><p>${text}</p></div></div>`;}
function renderHelp(){return `${heading('UNA COMUNIDAD QUE CUIDA','Red de Ayuda','Pequeños gestos. Una comunidad más preparada.',state.network.joined?badge('UNIDO · DEMO','green'):'')} ${state.network.joined?`<div class="section-toolbar"><h2>Alertas cercanas <span class="count">${state.network.alerts.filter(a=>!a.closed).length}</span></h2>${button(`${icon('plus')} Simular alerta cercana`,'network-sim','primary')}</div>${note('Solo se muestran escenarios ficticios. No estás conectado a una red real y nadie recibe tus acciones.')}<div class="alert-list">${state.network.alerts.filter(a=>!a.closed).length?state.network.alerts.filter(a=>!a.closed).map(a=>`<button class="card alert-card" data-action="network-detail" data-id="${a.id}"><span class="icon-tile amber">${icon('warning')}</span><span><span class="alert-meta">ALERTA SIMULADA · ZONA APROXIMADA</span><strong>Persona solicita orientación</strong><small>Sector de ejemplo · a unos 800 m (ficticio)</small></span>${icon('chevron')}</button>`).join(''):empty('users','Todo tranquilo en esta demo','Todavía no hay escenarios abiertos. Simula una alerta para explorar cómo se vería una solicitud de ayuda.')} </div>${button(`${icon('logout')} Salir de la red`,'network-leave','ghost')}`:`<div class="two-columns"><section class="card network-intro"><span class="large-icon red">${icon('users')}</span><p class="eyebrow">CIUDADANOS CUIDANDO CIUDADANOS</p><h2>Ayudar empieza<br>por estar cerca.</h2><p>Explora cómo una comunidad podría compartir solicitudes de ayuda con ubicación aproximada.</p>${badge('PARTICIPACIÓN VOLUNTARIA')}</section><section class="card"><h2>Ayuda con responsabilidad</h2><div class="feature-list">${feature('phone','No sustituye al 9-1-1','En una emergencia real, contacta a los servicios oficiales.')}${feature('lock','Ubicación exacta protegida','Los escenarios solo muestran una zona ficticia aproximada.')}${feature('shield','Tu seguridad va primero','No te pongas en riesgo ni intervengas en una situación peligrosa.')}</div><label class="checkbox-line"><input id="network-consent" type="checkbox" ${networkConsent?'checked':''}><span>Entiendo las reglas y acepto participar voluntariamente en esta demo.</span></label>${button('Unirme a la Red de Ayuda','network-join','primary full',networkConsent?'':'disabled')}${button('Quizás más tarde','network-later','ghost full')}</section></div>`}`;}
function renderRoute(){const t=state.trip;return `${heading('EN CAMINO','Cada llegada cuenta.','Prueba un trayecto y confirma que llegaste bien.')} ${t?`<div class="two-columns"><section class="card route-active"><span class="large-icon ${t.status==='active'?'green':'amber'}">${icon(t.status==='active'?'route':'clock')}</span>${badge(t.status==='active'?'TRAYECTO ACTIVO · DEMO':t.status==='verifying'?'VERIFICACIÓN SIMULADA':'ESCALAMIENTO SIMULADO',t.status==='active'?'green':'amber')}<h2>${esc(t.destination)}</h2><p>${t.status==='active'?'Tiempo restante':t.status==='verifying'?'¿Llegaste bien? Confirma antes de que termine el plazo.':'El plazo venció. Nadie recibió una notificación.'}</p><div class="large-timer" data-timer="trip">${t.status==='escalated'?'Sin respuesta':clock(remaining(t.status==='verifying'?t.verifyDeadline:t.deadline))}</div>${button(`${icon('check')} Llegué bien`,'trip-arrived','success full')}<div class="button-row">${button('Extender tiempo','trip-extend')}${button('Cancelar trayecto','trip-cancel','ghost')}</div>${t.status==='active'?button('Simular vencimiento (demo)','trip-expire','text-link full'):''}</section><section class="card"><h2>Detalles del trayecto</h2><dl class="facts"><div><dt>Destino</dt><dd>${esc(t.destination)}</dd></div><div><dt>Contacto elegido</dt><dd>${esc(t.contact.name)}</dd></div><div><dt>Teléfono</dt><dd>${esc(t.contact.phone)}</dd></div><div><dt>Tiempo inicial</dt><dd>${t.minutes} min</dd></div></dl>${note('Este contacto solo se utiliza para mostrar el flujo. No se comparte el trayecto ni se envían mensajes.')}<p class="form-hint">Al volver a la página se recalcula el tiempo. La web no ofrece supervisión fiable en segundo plano.</p></section></div>`:`<div class="two-columns"><form id="trip-form" class="card"><h2>Prepara tu trayecto</h2><label for="destination">¿A dónde vas?</label><div class="input-icon">${icon('pin')}<input id="destination" name="destination" placeholder="Ej. Mi casa, universidad…" required minlength="2" maxlength="120"></div><label for="trip-contact">Contacto de confianza</label><select name="contact" id="trip-contact" required><option value="">Selecciona un contacto</option>${state.contacts.map(c=>`<option value="${c.id}">${esc(c.name)} · ${esc(c.relation)}</option>`).join('')}</select>${!state.contacts.length?`<p class="form-hint">Necesitas un contacto para empezar.</p><button type="button" class="text-link" data-page="contacts">${icon('plus')} Agregar contacto</button>`:''}<label for="minutes">Tiempo estimado (minutos)</label><input name="minutes" id="minutes" type="number" value="15" min="1" max="1440" step="1" required><p class="form-error" role="alert"></p><button class="btn primary full" type="submit" ${!state.contacts.length?'disabled':''}>${icon('route')} Iniciar trayecto de prueba</button></form><section class="card journey-explainer"><p class="eyebrow">ASÍ FUNCIONA</p><h2>Un plan sencillo<br>para tu camino.</h2><ol class="steps"><li><span>01</span><div><h3>Elige tu destino</h3><p>Agrega un contacto y estima la duración.</p></div></li><li><span>02</span><div><h3>Haz tu recorrido</h3><p>Extiende el tiempo cuando lo necesites.</p></div></li><li><span>03</span><div><h3>Confirma tu llegada</h3><p>Si vence el plazo, verás una verificación simulada.</p></div></li></ol>${note('Ningún contacto recibirá avisos. Todos los resultados se guardan en tu historial local.')}</section></div>`}`;}
function renderMore(){return `${heading('A TU MEDIDA','Tu espacio personal','Personas, información y opciones de seguridad.')}<div class="more-grid">${[['history','history','Central / Historial','Todas tus pruebas y sus resultados'],['contacts','users','Contactos','Las personas con las que cuentas'],['security','lock','Seguridad','PINs y verificaciones de Tutor'],['profile','user','Perfil','Tu información personal y médica']].map(([id,ic,title,text])=>`<button class="card more-card" data-page="${id}"><span class="icon-tile ${id==='security'?'red':''}">${icon(ic)}</span><span><strong>${title}</strong><small>${text}</small></span>${icon('chevron')}</button>`).join('')}</div>${note('Esta experiencia funciona con datos de este navegador. Los PINs y escenarios son de práctica; no sustituyen un sistema de seguridad real.')}`;}
function eventRow(e){const good=/Cancelad|Llegada|Confirmad|Guardad|Cerrad/.test(e.status);return `<button class="event-row" data-action="event-detail" data-id="${e.id}"><span class="icon-tile ${good?'green':e.status.includes('Escalamiento')?'amber':''}">${icon(e.type==='Ruta'?'route':e.type==='Drive'?'car':e.type==='Tutor'?'lock':e.type==='Red'?'users':'history')}</span><span class="event-copy"><strong>${esc(e.title)}</strong><small>${esc(e.type)} · ${date(e.at)} · ${time(e.at)}</small></span><span class="event-status">${badge(esc(e.status),good?'green':'muted')}</span>${icon('chevron')}</button>`;}
function renderHistory(){return `${heading('CENTRAL DE ACTIVIDAD','Tu historial','Cada paso de tus pruebas, en un solo lugar.',badge(`${state.history.length} REGISTROS`))}${state.history.length?`<div class="history-list card">${state.history.map(eventRow).join('')}</div>`:`<section class="card">${empty('history','Tu historia empieza aquí','Cuando pruebes SOS, Drive, Ruta o Tutor, podrás revisar cada resultado en este espacio.',button('Explorar SOS','go-sos','primary'))}</section>`}`;}
function renderContacts(){return `${heading('TU CÍRCULO DE CONFIANZA','Personas que están para ti.','Guarda contactos para probar SOS y En Camino.',button(`${icon('plus')} Agregar contacto`,'contact-add','primary'))}${state.contacts.length?`<div class="contacts-grid">${state.contacts.map(c=>`<article class="card contact-card"><span class="avatar big">${esc(initials(c.name))}</span><div class="contact-info"><h3>${esc(c.name)}</h3><span>${esc(c.relation)}</span><p>${esc(c.phone)}</p></div><div class="contact-tools"><button class="icon-button" data-action="contact-edit" data-id="${c.id}" aria-label="Editar a ${esc(c.name)}">${icon('edit')}</button><button class="icon-button danger-text" data-action="contact-delete" data-id="${c.id}" aria-label="Eliminar a ${esc(c.name)}">${icon('trash')}</button></div></article>`).join('')}</div>`:`<section class="card">${empty('users','La tranquilidad también tiene nombre.','Agrega una persona de confianza. Para practicar, puedes usar un nombre ficticio y un teléfono de ejemplo.',button(`${icon('plus')} Agregar contacto`,'contact-add','primary'))}</section>`}${note('Los contactos se guardan solo en este navegador. Agregarlos no les envía invitaciones ni notificaciones.')}`;}
function renderSecurity(){return `${heading('TU SEGURIDAD, A TU MANERA','Un paso por delante.','Configura y practica tus protocolos de verificación.')}<div class="tabs" role="tablist" aria-label="Opciones de seguridad"><button role="tab" aria-selected="${securityTab==='pins'}" tabindex="${securityTab==='pins'?0:-1}" id="tab-pins" aria-controls="security-panel" data-action="tab-pins">${icon('lock')} PINs</button><button role="tab" aria-selected="${securityTab==='tutor'}" tabindex="${securityTab==='tutor'?0:-1}" id="tab-tutor" aria-controls="security-panel" data-action="tab-tutor">${icon('shield')} Tutor</button></div><div id="security-panel" role="tabpanel" aria-labelledby="tab-${securityTab}">${securityTab==='pins'?`<div class="two-columns"><form class="card" id="pins-form"><h2>Códigos de cancelación</h2><p>${state.pins?'Tus PINs están configurados. Introduce dos nuevos para cambiarlos.':'Crea dos códigos diferentes para practicar.'}</p><label for="normal-pin">PIN de cancelación normal</label><input name="normal" id="normal-pin" type="password" inputmode="numeric" pattern="[0-9]{4,6}" minlength="4" maxlength="6" autocomplete="new-password" required><p class="form-hint">Finaliza la prueba e indica que estás a salvo.</p><label for="duress-pin">PIN de coacción</label><input name="duress" id="duress-pin" type="password" inputmode="numeric" pattern="[0-9]{4,6}" minlength="4" maxlength="6" autocomplete="new-password" required><p class="form-hint">Muestra una cancelación aparente con seguimiento simulado.</p><p class="form-error" role="alert"></p><button class="btn primary full" type="submit">Guardar PINs</button></form><section class="card"><span class="icon-tile amber">${icon('lock')}</span><h2>Conoce ambos escenarios</h2><div class="feature-list">${feature('check','Cancelación normal','Tu código de cancelación detiene la prueba y registra el resultado.')}${feature('shield','Cancelación aparente','El PIN de coacción simula que la alerta se cierra y registra un seguimiento de demostración.')}</div>${note('Usa códigos solo para esta demo. Se guardan como resúmenes criptográficos locales; esta web no es una herramienta real contra la coacción.')} ${button('Practicar con un PIN','pin-practice','secondary full',state.pins?'':'disabled')}</section></div>`:renderTutor()}</div>`;}
function renderTutor(){const t=state.tutor;return `<div class="two-columns"><section class="card tutor-card"><span class="large-icon ${t.status==='escalated'?'amber':'green'}">${icon('shield')}</span>${badge('TUTOR · DEMOSTRACIÓN')}<h2>${({normal:'Todo en orden',waiting:'Esperando tu respuesta',confirmed:'Confirmaste que estás bien',escalated:'Escalamiento simulado'})[t.status]}</h2><p>${t.status==='waiting'?'Una solicitud ficticia espera tu confirmación.':t.status==='escalated'?'Se agotó el plazo. No se contactó a nadie.':'Practica una verificación iniciada por otra persona.'}</p>${t.status==='waiting'?`<div class="large-timer" data-timer="tutor">${clock(remaining(t.deadline))}</div>${button(`${icon('check')} Estoy bien`,'tutor-ok','success full')}`:button('Simular solicitud externa','tutor-start','primary full')}</section><section class="card"><h2>Una comprobación de tranquilidad</h2><div class="feature-list">${feature('bell','Solicitud ficticia','Pulsa el botón para representar una petición externa. No existe una conexión con otra persona.')}${feature('clock','20 segundos para responder','Confirma que estás bien o deja que el tiempo termine.')}${feature('history','Resultado visible','Revisa la confirmación o el escalamiento simulado en el historial.')}</div>${note('El seguimiento es una simulación local y solo se procesa mientras la página puede ejecutarse o al volver a ella.')}</section></div>`;}
function renderProfile(){const p=state.profile;return `${heading('INFORMACIÓN PERSONAL','Tu perfil','Los datos que eliges tener a mano.',!profileEditing?button(`${icon('edit')} Editar información`,'profile-edit','secondary'):'')} ${profileEditing?`<form class="card profile-form" id="profile-form"><h2>Editar información</h2><div class="form-grid"><div><label for="profile-name">Nombre completo</label><input name="name" id="profile-name" value="${esc(p.name)}" required minlength="2" maxlength="100" autocomplete="name"></div><div><label for="profile-phone">Teléfono</label><input name="phone" id="profile-phone" value="${esc(p.phone)}" type="tel" required autocomplete="tel"></div><div><label for="blood">Tipo de sangre</label><select id="blood" name="blood">${['No especificado','A+','A−','B+','B−','AB+','AB−','O+','O−'].map(x=>`<option ${p.blood===x?'selected':''}>${x}</option>`).join('')}</select></div><div><label for="allergies">Alergias</label><input name="allergies" id="allergies" value="${esc(p.allergies)}" maxlength="300" placeholder="No especificadas"></div><div class="span-two"><label for="meds">Medicamentos</label><textarea id="meds" name="meds" maxlength="500" rows="3" placeholder="No especificados">${esc(p.meds)}</textarea></div></div><p class="form-error" role="alert"></p><div class="button-row"><button class="btn primary" type="submit">Guardar cambios</button>${button('Cancelar','profile-cancel','ghost','type="button"')}</div></form>`:`<div class="two-columns"><section class="card profile-summary"><span class="avatar profile-avatar">${p.name?esc(initials(p.name)):icon('user')}</span><h2>${esc(p.name||'Tu perfil está por completar')}</h2><p>${p.phone?esc(p.phone):'Agrega la información que quieras tener a mano.'}</p>${badge(p.name?'INFORMACIÓN LOCAL':'SIN DATOS PERSONALES')}<dl class="facts"><div><dt>Nombre</dt><dd>${esc(p.name||'No especificado')}</dd></div><div><dt>Teléfono</dt><dd>${esc(p.phone||'No especificado')}</dd></div></dl></section><section class="card"><div class="card-top"><h2>Información médica</h2><span class="icon-tile red">${icon('heart')}</span></div>${feature('drop','Tipo de sangre',esc(p.blood))}${feature('plus','Alergias',esc(p.allergies||'No especificadas'))}${feature('heart','Medicamentos',esc(p.meds||'No especificados'))}</section></div>`}${note('La información se guarda en este navegador. No se comparte con servicios de emergencia. Puedes usar datos ficticios para recorrer esta demo.')}`;}
function openModal(type,data={}){returnFocus=document.activeElement;modal={type,...data};renderModal();if(!dialog.open)dialog.showModal();}
function closeModal(){dialog.close();modal=null;returnFocus?.isConnected&&returnFocus.focus();}
function renderModal(){if(!modal)return;const m=modal;let title='',content='';
 if(m.type==='about'){title='Una demo para explorar con calma';content=`${badge('DEMOSTRACIÓN INTERACTIVA','amber')}<p>Todos los SOS, impactos, avisos de la red, trayectos y verificaciones son pruebas locales.</p><ul class="plain-list"><li>No se envían SMS, correos, notificaciones ni alertas al 9-1-1.</li><li>«Mi ubicación» puede usar la ubicación real si autorizas al navegador. No se comparte.</li><li>«Llamar» permite abrir tu marcador. Esa acción queda fuera de la simulación.</li><li>Los datos permanecen en este navegador y no se sincronizan.</li></ul>${button('Entendido','close-modal','primary full')}`;}
 if(m.type==='incident'){const i=state.incident;if(!i)return;title=i.type==='SOS'?'Prueba de SOS iniciada':i.type==='Drive'?'Impacto simulado':'Accidente de demostración';content=`${badge('NO SE ENVIARÁ UNA ALERTA REAL','red')}<div class="countdown"><span data-timer="incident">${remaining(i.deadline)}</span><small>segundos para cancelar</small></div><p>Al finalizar, el resultado se guardará únicamente en tu historial.</p><label for="incident-note">Detalle del incidente (opcional)</label><textarea id="incident-note" maxlength="400" placeholder="Describe el escenario de prueba…">${esc(i.note)}</textarea><label for="incident-contact">Contacto para esta prueba</label><select id="incident-contact"><option value="">Sin contacto</option>${state.contacts.map(c=>`<option value="${c.id}" ${i.contactId===c.id?'selected':''}>${esc(c.name)} · ${esc(c.phone)}</option>`).join('')}</select>${!state.contacts.length?'<p class="form-hint">No tienes contactos guardados. Puedes agregarlos en Más → Contactos.</p>':''}<div class="stack">${button('Estoy bien · Cancelar prueba','incident-cancel','success full')}${state.pins?button('Cancelar con PIN','incident-pin','secondary full'):''}</div>`;}
 if(m.type==='result'){title=m.title||'Simulación finalizada';content=`<div class="result-icon ${m.tone||'green'}">${icon(m.tone==='amber'?'warning':'check')}</div><h3 class="center">${esc(m.status||'Resultado guardado')}</h3><p class="center">${esc(m.detail||'La prueba quedó registrada en tu historial. No se envió una alerta real.')}</p>${button('Ver en el historial','result-history','primary full')}${button('Continuar','close-modal','ghost full')}`;}
 if(m.type==='contact'){const c=m.contact||{};title=c.id?'Editar contacto':'Nuevo contacto';content=`<form id="contact-form" data-id="${c.id||''}"><label for="contact-name">Nombre</label><input name="name" id="contact-name" value="${esc(c.name||'')}" required minlength="2" maxlength="80" placeholder="Ej. Persona de confianza"><label for="contact-phone">Teléfono</label><input name="phone" id="contact-phone" type="tel" value="${esc(c.phone||'')}" required maxlength="25" placeholder="Ej. +1 202 555 0100"><label for="relation">Parentesco o relación</label><input name="relation" id="relation" value="${esc(c.relation||'')}" required maxlength="50" placeholder="Ej. Familiar, amistad…"><p class="form-error" role="alert"></p><div class="button-row">${button('Cancelar','close-modal','ghost','type="button"')}<button type="submit" class="btn primary">${c.id?'Guardar cambios':'Agregar contacto'}</button></div></form>`;}
 if(m.type==='confirm'){title=m.title;content=`<p>${esc(m.text)}</p><div class="button-row">${button('Volver','close-modal','secondary')}${button(m.label||'Confirmar','confirm','danger')}</div>`;}
 if(m.type==='location'){title='Mi ubicación';content=`${geo.status==='loading'?'<div class="loading" role="status">Solicitando ubicación al navegador…</div>':geo.status==='success'?`<div class="location-result"><span class="large-icon green">${icon('pin')}</span><h3>Ubicación obtenida</h3><p>${geo.lat.toFixed(6)}, ${geo.lng.toFixed(6)}</p><p class="form-hint">Precisión aproximada: ${Math.round(geo.accuracy)} m. No se ha compartido.</p><a class="btn primary full" href="https://www.google.com/maps?q=${geo.lat},${geo.lng}" target="_blank" rel="noopener noreferrer">Abrir en el mapa ${icon('arrow')}</a></div>`:geo.status==='error'?note(esc(geo.message),'amber'):note('Tu navegador te pedirá permiso. La ubicación se usa solo aquí y no se guarda en el historial.')}<div class="stack">${button(geo.status==='error'?'Volver a intentar':'Obtener mi ubicación','geo-request','secondary full',geo.status==='loading'?'disabled':'')}</div><div class="separator"></div><h3>O escribe una referencia</h3><form id="manual-location"><label for="manual-place">Dirección o lugar cercano</label><input id="manual-place" name="place" required minlength="3" maxlength="180" placeholder="Calle, sector o punto de referencia"><p class="form-error" role="alert"></p><button class="btn secondary full" type="submit">Usar ubicación manual</button></form>${geo.manual?`<p class="success-text">Referencia manual: ${esc(geo.manual)}</p><a class="text-link" href="https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(geo.manual)}" target="_blank" rel="noopener noreferrer">Buscar referencia en el mapa ${icon('arrow')}</a>`:''}`;}
 if(m.type==='call'){title='Llamar al 9-1-1';content=`<span class="large-icon red">${icon('phone')}</span><p>Si hay una emergencia real, puedes abrir el marcador de tu teléfono.</p>${note('Esta acción es real: abrirá una aplicación de llamadas. La demo no realiza ni confirma la llamada. En una computadora puede no haber una aplicación compatible.','amber')}<a class="btn danger full" href="tel:911">${icon('phone')} Abrir marcador: 9-1-1</a>${button('Volver a la demo','close-modal','ghost full')}`;}
 if(m.type==='assistance'){title='¿Cómo podemos orientarte?';content=`<div class="feature-list">${feature('shield','Busca un lugar seguro','Evita exponerte a un peligro para continuar con la aplicación.')}${feature('phone','Ante una emergencia real','Abre el marcador y contacta al 9-1-1. Describe dónde estás y sigue sus indicaciones.')}${feature('users','Ten tus contactos a mano','Consulta las personas guardadas en tu círculo de confianza.')}</div><div class="stack">${button(`${icon('phone')} Opciones de llamada`,'call','primary full')}${button(`${icon('pin')} Consultar mi ubicación`,'location','secondary full')}${button('Ver mis contactos','go-contacts','ghost full')}</div>`;}
 if(m.type==='event'){const e=state.history.find(x=>x.id===m.id);if(!e)return;title=e.title;content=`${badge('REGISTRO LOCAL · DEMO','amber')}<dl class="facts"><div><dt>Tipo</dt><dd>${esc(e.type)}</dd></div><div><dt>Fecha</dt><dd>${date(e.at)}</dd></div><div><dt>Hora</dt><dd>${time(e.at)}</dd></div><div><dt>Estado</dt><dd>${esc(e.status)}</dd></div></dl><p>${esc(e.detail)}</p>${button('Cerrar detalle','close-modal','secondary full')}`;}
 if(m.type==='network'){title='Solicitud de orientación';content=`${badge('ESCENARIO FICTICIO','amber')}<p>Una persona ficticia necesita orientación para encontrar un punto de asistencia en el sector de ejemplo.</p><dl class="facts"><div><dt>Zona aproximada</dt><dd>Sector de ejemplo</dd></div><div><dt>Distancia ficticia</dt><dd>Unos 800 m</dd></div><div><dt>Estado</dt><dd>Abierta · simulación</dd></div></dl>${note('No se revela una ubicación exacta. No existe una persona real esperando ayuda. No debes desplazarte ni ponerte en riesgo.')} ${button('Cerrar alerta simulada','network-close','primary full')}`;}
 if(m.type==='extend'){title='Un poco más de tiempo';content=`<form id="extend-form"><label for="extra-minutes">Minutos adicionales</label><input id="extra-minutes" name="minutes" type="number" min="1" max="180" step="1" value="5" required><p class="form-error" role="alert"></p><button class="btn primary full" type="submit">Extender trayecto</button></form>`;}
 if(m.type==='pin'){title=m.incident?'Cancelar con PIN':'Práctica de PIN';content=`${badge('SIMULACIÓN','amber')}<p>Introduce uno de tus PINs guardados para probar su efecto.${m.incident?' La cuenta regresiva sigue activa.':''}</p>${m.incident?'<p>Tiempo restante: <strong data-timer="incident"></strong> s</p>':''}<form id="pin-test-form"><label for="test-pin">Tu PIN de práctica</label><input type="password" inputmode="numeric" id="test-pin" name="pin" pattern="[0-9]{4,6}" minlength="4" maxlength="6" required autocomplete="off"><p class="form-error" role="alert"></p><button class="btn primary full" type="submit">Probar PIN</button></form>`;}
 dialog.innerHTML=`<div class="modal-head"><h2 id="modal-title">${title}</h2><button class="icon-button" data-action="close-modal" aria-label="${m.type==='incident'?'Cerrar y cancelar prueba':'Cerrar ventana'}">${icon('x')}</button></div><div class="modal-body">${content}</div>`;updateTimers();}
function commitRender(){persist();render();}
function runIncident(type,seconds){if(startIncident(state,type,seconds)){persist();render();openModal('incident');}else openModal('incident');}
function cancelIncident(){const event=endIncident(state,'Cancelada');commitRender();openModal('result',{title:'Prueba cancelada',status:'Confirmaste que estás bien',detail:event?.detail});}
function confirm(title,text,action,label){openModal('confirm',{title,text,action,label});}
async function requestLocation(){if(!navigator.geolocation){geo={...geo,status:'error',message:'Este navegador no ofrece geolocalización. Puedes escribir una referencia manual.'};renderModal();return;}geo.status='loading';renderModal();navigator.geolocation.getCurrentPosition(pos=>{geo={...geo,status:'success',lat:pos.coords.latitude,lng:pos.coords.longitude,accuracy:pos.coords.accuracy};if(modal?.type==='location')renderModal();},error=>{geo={...geo,status:'error',message:error.code===1?'El permiso fue denegado. Puedes habilitarlo en los ajustes del navegador o escribir una referencia manual.':error.code===3?'La solicitud tardó demasiado. Intenta en una zona con mejor señal o usa la ubicación manual.':'No se pudo obtener tu ubicación. Revisa tu conexión y permisos o escribe una referencia manual.'};if(modal?.type==='location')renderModal();},{enableHighAccuracy:false,timeout:12000,maximumAge:60000});}
async function hashPin(pin,salt){const bytes=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(salt+pin));return Array.from(new Uint8Array(bytes)).map(b=>b.toString(16).padStart(2,'0')).join('');}
function formError(form,message){const el=form.querySelector('.form-error');el.textContent=message;}
async function handleAction(action,el){
 switch(action){
 case 'about':openModal('about');break;
 case 'sos':runIncident('SOS',10);break;
 case 'accident':runIncident('Accidente',15);break;
 case 'drive-impact':runIncident('Drive',state.drive.seconds);break;
 case 'incident-cancel':cancelIncident();break;
 case 'incident-pin':openModal('pin',{incident:true});break;
 case 'close-modal':if(modal?.type==='incident'){cancelIncident();}else if(modal?.type==='pin'&&modal.incident&&state.incident){openModal('incident');}else closeModal();break;
 case 'result-history':closeModal();navigate('history');break;
 case 'location':openModal('location');break;
 case 'geo-request':requestLocation();break;
 case 'call':openModal('call');break;
 case 'assistance':openModal('assistance');break;
 case 'go-contacts':closeModal();navigate('contacts');break;
 case 'go-sos':navigate('sos');break;
 case 'physical':physicalOpen=!physicalOpen;render();break;
 case 'record-pattern':recording=true;practice=false;patternDraft=[];patternMessage='';render();break;
 case 'practice-pattern':practice=!practice;recording=false;practiceInput=[];patternMessage='';render();break;
 case 'pattern-plus':case 'pattern-minus':{const key=action==='pattern-plus'?'VOL+':'VOL−';if(recording){if(patternDraft.length<6)patternDraft.push(key);else toast('El patrón admite hasta 6 pulsaciones.',true);}if(practice){practiceInput.push(key);if(practiceInput.length===state.pattern.length){const match=JSON.stringify(practiceInput)===JSON.stringify(state.pattern);patternMessage=match?'Patrón reconocido. Práctica completada; no se envió un SOS.':'El patrón no coincide. Reinicia las pulsaciones para intentarlo de nuevo.';addEvent(state,'SOS físico','Práctica de patrón',match?'Completada':'No coincide',patternMessage);persist();practice=false;}}render();break;}
 case 'reset-pattern':patternDraft=[];practiceInput=[];patternMessage='';render();break;
 case 'save-pattern':if(patternDraft.length>=3){state.pattern=[...patternDraft];recording=false;patternMessage='Patrón guardado. Puedes probarlo en modo práctica.';commitRender();toast('Patrón guardado.');}break;
 case 'drive-config':driveEditing=true;render();break;
 case 'drive-config-cancel':driveEditing=false;render();break;
 case 'drive-off':confirm('¿Desactivar Drive?','La protección de demostración dejará de estar activa.',()=>{state.drive.active=false;addEvent(state,'Drive','Drive desactivado','Desactivado','Se desactivó el modo de demostración.');driveEditing=false;commitRender();toast('Drive desactivado.');},'Desactivar');break;
 case 'network-join':if(networkConsent){state.network.joined=true;addEvent(state,'Red','Incorporación a la Red de Ayuda','Unido · demo','Participación voluntaria en la red simulada. No hay conexiones reales.');commitRender();toast('Te uniste a la red de demostración.');}break;
 case 'network-later':navigate('sos');break;
 case 'network-sim':{const a={id:uid(),at:Date.now(),closed:false};state.network.alerts.unshift(a);addEvent(state,'Red','Alerta cercana simulada','Abierta','Escenario ficticio en una zona de ejemplo; no se avisó a personas reales.');commitRender();toast('Alerta de demostración creada.');break;}
 case 'network-detail':openModal('network',{id:el.dataset.id});break;
 case 'network-close':{const a=state.network.alerts.find(x=>x.id===modal.id);if(a)a.closed=true;addEvent(state,'Red','Alerta cercana cerrada','Cerrada','El escenario ficticio fue cerrado localmente.');closeModal();commitRender();toast('Alerta simulada cerrada.');break;}
 case 'network-leave':confirm('¿Salir de la red de demostración?','Las alertas ficticias abiertas se cerrarán. Puedes volver a unirte cuando quieras.',()=>{state.network.joined=false;state.network.alerts.forEach(a=>a.closed=true);networkConsent=false;addEvent(state,'Red','Salida de la red','Cerrada','Participación de demostración finalizada.');commitRender();},'Salir de la red');break;
 case 'trip-arrived':finishTrip(state,'Llegada confirmada');commitRender();toast('Llegada registrada. No se enviaron mensajes.');break;
 case 'trip-extend':openModal('extend');break;
 case 'trip-cancel':confirm('¿Cancelar este trayecto?','Se cerrará el trayecto de prueba y se guardará su cancelación.',()=>{finishTrip(state,'Cancelado');commitRender();toast('Trayecto cancelado.');},'Cancelar trayecto');break;
 case 'trip-expire':if(state.trip){state.trip.deadline=Date.now();processTimers();}break;
 case 'contact-add':openModal('contact');break;
 case 'contact-edit':openModal('contact',{contact:state.contacts.find(c=>c.id===el.dataset.id)});break;
 case 'contact-delete':{const c=state.contacts.find(c=>c.id===el.dataset.id);confirm(`¿Eliminar a ${c.name}?`,'Ya no aparecerá al iniciar nuevos SOS o trayectos. Un trayecto activo conserva el contacto elegido al iniciarse.',()=>{state.contacts=state.contacts.filter(x=>x.id!==c.id);commitRender();toast('Contacto eliminado.');},'Eliminar contacto');break;}
 case 'event-detail':openModal('event',{id:el.dataset.id});break;
 case 'tab-pins':securityTab='pins';render();document.querySelector('#tab-pins').focus();break;
 case 'tab-tutor':securityTab='tutor';render();document.querySelector('#tab-tutor').focus();break;
 case 'pin-practice':openModal('pin');break;
 case 'tutor-start':state.tutor={status:'waiting',deadline:Date.now()+20000};addEvent(state,'Tutor','Solicitud externa simulada','Esperando respuesta','Solicitud ficticia. Plazo de 20 segundos; no fue iniciada por una persona real.');commitRender();break;
 case 'tutor-ok':state.tutor={status:'confirmed',deadline:null};addEvent(state,'Tutor','Estoy bien','Confirmado','El usuario confirmó su bienestar en la demostración. No se notificó a terceros.');commitRender();toast('Respuesta registrada.');break;
 case 'profile-edit':profileEditing=true;render();break;
 case 'profile-cancel':profileEditing=false;render();break;
 case 'confirm':{const fn=modal.action;closeModal();fn();break;}
 }
}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action],[data-page]');if(!el||el.disabled)return;if(el.dataset.page){navigate(el.dataset.page);return;}e.preventDefault();handleAction(el.dataset.action,el);});
dialog.addEventListener('cancel',e=>{e.preventDefault();handleAction('close-modal');});
document.addEventListener('keydown',e=>{if(e.target.getAttribute('role')==='tab'&&['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();handleAction(e.key==='Home'?'tab-pins':e.key==='End'?'tab-tutor':securityTab==='pins'?'tab-tutor':'tab-pins');}});
document.addEventListener('input',e=>{
 if(e.target.id==='seconds')document.querySelector('#seconds-output').textContent=`${e.target.value} segundos`;
 if(e.target.closest('#drive-form')){const f=document.querySelector('#drive-form');document.querySelector('#drive-submit').disabled=!(f.elements.consent.checked&&f.elements.transport.value&&f.elements.placement.value);}
 if(e.target.id==='network-consent'){networkConsent=e.target.checked;document.querySelector('[data-action="network-join"]').disabled=!networkConsent;}
 if(e.target.id==='incident-note'&&state.incident){state.incident.note=e.target.value;persist();}
 if(e.target.id==='incident-contact'&&state.incident){state.incident.contactId=e.target.value;persist();}
});
document.addEventListener('submit',async e=>{e.preventDefault();const f=e.target;if(f.id.startsWith('real-'))return;const data=Object.fromEntries(new FormData(f));
 if(f.id==='contact-form'){const id=f.dataset.id;const err=validateContact(state,data,id);if(err){formError(f,err);return;}const c={id:id||uid(),name:data.name.trim(),phone:data.phone.trim(),relation:data.relation.trim()};if(id)state.contacts=state.contacts.map(x=>x.id===id?c:x);else state.contacts.push(c);closeModal();commitRender();toast(id?'Contacto actualizado.':'Contacto agregado.');}
 if(f.id==='drive-form'){if(!data.consent||!data.transport||!data.placement){formError(f,'Acepta el consentimiento y completa las preferencias.');return;}state.drive={active:true,consent:true,transport:data.transport,placement:data.placement,seconds:Number(data.seconds)};addEvent(state,'Drive',driveEditing?'Preferencias de Drive actualizadas':'Drive activado','Activo · demo',`${data.transport}; dispositivo en ${data.placement.toLowerCase()}; cuenta regresiva de ${data.seconds} segundos. Detección únicamente simulada.`);driveEditing=false;commitRender();toast('Drive activo en modo demostración.');}
 if(f.id==='trip-form'){const err=startTrip(state,data.destination,data.contact,Number(data.minutes));if(err){formError(f,err);return;}commitRender();toast('Trayecto de demostración iniciado.');}
 if(f.id==='extend-form'){const mins=Number(data.minutes);if(!Number.isInteger(mins)||mins<1||mins>180){formError(f,'Elige entre 1 y 180 minutos enteros.');return;}if(!state.trip){closeModal();return;}state.trip.deadline=Math.max(Date.now(),state.trip.deadline)+mins*60000;state.trip.status='active';delete state.trip.verifyDeadline;addEvent(state,'Ruta','Tiempo extendido','Activo',`Se agregaron ${mins} minutos al trayecto hacia ${state.trip.destination}. No se notificó a terceros.`);closeModal();commitRender();toast(`Se agregaron ${mins} minutos.`);}
 if(f.id==='manual-location'){if(data.place.trim().length<3){formError(f,'Escribe una referencia de al menos 3 caracteres.');return;}geo.manual=data.place.trim();renderModal();toast('Referencia manual lista. No se ha compartido.');}
 if(f.id==='profile-form'){if(data.name.trim().length<2){formError(f,'Escribe un nombre de al menos 2 caracteres.');return;}if(!validPhone(data.phone)){formError(f,'Escribe un teléfono válido de 10 a 15 dígitos.');return;}state.profile=Object.fromEntries(Object.entries(data).map(([k,v])=>[k,v.trim()]));profileEditing=false;commitRender();toast('Perfil actualizado.');}
 if(f.id==='pins-form'){const err=validatePins(data.normal,data.duress);if(err){formError(f,err);return;}try{const salt=crypto.randomUUID();state.pins={salt,normal:await hashPin(data.normal,salt),duress:await hashPin(data.duress,salt)};commitRender();toast('PINs guardados. Sus valores no se muestran.');}catch{formError(f,'No se pudieron guardar de forma segura. Abre la app en HTTPS o localhost.');}}
 if(f.id==='pin-test-form'){const isIncident=modal.incident;const incidentId=state.incident?.id;try{const hash=await hashPin(data.pin,state.pins.salt);if(hash!==state.pins.normal&&hash!==state.pins.duress){formError(f,'El PIN no coincide. Vuelve a intentarlo.');return;}if(isIncident&&state.incident?.id!==incidentId){toast('La cuenta regresiva ya terminó. Consulta el resultado en el historial.');return;}const duress=hash===state.pins.duress;const status=duress?'Seguimiento simulado':'Cancelación normal';if(isIncident)endIncident(state,duress?'Cancelación aparente · seguimiento simulado':'Cancelada con PIN');addEvent(state,'Seguridad','Práctica de PIN',status,duress?'La interfaz representa una cancelación aparente. Solo se registra un seguimiento local simulado; no hay rastreo ni alertas externas.':'El PIN de cancelación normal fue reconocido. La prueba finalizó sin alertas externas.');commitRender();openModal('result',{title:duress?'Cancelación aparente · demo':'Cancelación normal',status,detail:duress?'En un sistema real este escenario representaría seguimiento. Aquí solo se registra la simulación en el historial.':'PIN reconocido. La prueba se ha cancelado y el resultado quedó registrado.',tone:duress?'amber':'green'});}catch{formError(f,'No se pudo comprobar el PIN en este navegador.');}}
});
function updateTimers(){document.querySelectorAll('[data-timer]').forEach(el=>{if(el.dataset.timer==='incident'&&state.incident)el.textContent=remaining(state.incident.deadline);if(el.dataset.timer==='trip'&&state.trip)el.textContent=state.trip.status==='escalated'?'Sin respuesta':clock(remaining(state.trip.status==='verifying'?state.trip.verifyDeadline:state.trip.deadline));if(el.dataset.timer==='tutor'&&state.tutor.status==='waiting')el.textContent=clock(remaining(state.tutor.deadline));});}
function processTimers(){const changes=advanceTime(state);if(changes.length){commitRender();for(const c of changes){if(c.kind==='incident'){if(modal?.type==='incident'||(modal?.type==='pin'&&modal.incident)){openModal('result',{title:'Prueba finalizada',detail:c.event.detail});}else toast('Simulación finalizada. Resultado disponible en el historial.');}if(c.kind==='trip-check')toast('Terminó el tiempo del trayecto. Confirma tu llegada en Ruta.');if(c.kind==='trip-escalated')toast('Verificación de Ruta vencida. Escalamiento simulado registrado.');if(c.kind==='tutor-escalated')toast('Tutor: plazo vencido. Se registró un escalamiento simulado.');}}updateTimers();}
setInterval(processTimers,500);document.addEventListener('visibilitychange',()=>{if(!document.hidden)processTimers();});
render();if(mode==='real')realUI.init();processTimers();if(state.incident)openModal('incident');if(loaded.error)toast(loaded.error,true);
